                                }
                                else
                                {
                                    // API call failed / returned error text
                                    ScriptManager.RegisterStartupScript(this, this.GetType(), "msg",
                                        "alert('API Upload Failed: " + result.Replace("'", "").Replace("\n", " ").Replace("\r", "") + "');", true);
                                }
                            }
                            else
                            {
                                File.AppendAllText(logPath, DateTime.Now + " | ERROR: File does not exist at path." + Environment.NewLine);
                                ScriptManager.RegisterStartupScript(this, this.GetType(), "msg",
                                    "alert('Checklist file not found');", true);
                            }

                            File.AppendAllText(logPath, DateTime.Now + " | btnSendApi_Click ENDED" + Environment.NewLine);
                        }
                        catch (Exception ex)
                        {
                            File.AppendAllText(logPath, DateTime.Now + " | EXCEPTION: " + ex.ToString() + Environment.NewLine);
                            Connection.Error_Msg(ex.Message);
                        }
                    }
                }
                
                ////-----------------Skylift and Airlift On 21Sep2015-----------------------------//



                ds_Gen.Dispose();
                //dsI.Dispose();
                dss.Dispose();
                dssAss.Dispose();
                //ds_comn.Dispose();
                ds_License.Dispose();
                //ds_SW.Dispose();
                GC.Collect();

                //string finalhtmltext = "";

                if (lbl.Text != "")
                {
                    string imgfolder = Server.MapPath("~/images//arrow.png");

                    //lbl.Text = "<div style='width:1px; height:1px'><a href='Mail_Send.aspx'> <img src='http://eroyalimpex.co.in/images/arrow.png' tooltip='Send Mail'  alt='send mail'/> </a></div>" + lbl.Text;
                    //lbl.Text = "<div style='width:1px; height:1px'><a href='Mail_Send.aspx'> <img src='http://eroyalimpex.net/images/arrow.png' tooltip='Send Mail'  alt='send mail'/> </a></div>" + lbl.Text;
                    //lbl.Text = "<div style='width:1px; height:1px'><a href='Mail_Send.aspx'> <img src='http://eroyalimpex.org/images/arrow.png' tooltip='Send Mail'  alt='send mail'/> </a></div>" + lbl.Text;
                    //lbl.Text = "<div style='width:1px; height:1px'><a href='Mail_Send.aspx'> <img src='http://eroyalimpex.in/images/icons/sendmail50.png' tooltip='Send Mail'  alt='send mail'/> </a></div>" + lbl.Text;

                    //lbl.Text = "<div style='width:1px; height:1px'><a href='Mail_Send.aspx'> <img src='https://impex.boxcoworld.com/images/arrow.png' tooltip='Send Mail'  alt='send mail'/> </a></div>" + lbl.Text;
                    lbl.Text = "<div style='width:1px; height:1px'><a href='Mail_Send.aspx'> <img src='" + imgfolder + "' tooltip='Send Mail' alt='send mail'/> </a></div>" + lbl.Text;


                    Response.Clear();
                    Response.Buffer = true;
                    Response.ContentType = "application/pdf";
                    Response.AddHeader("content-disposition", "inline;filename=" + filename1 + "");
                    Response.Cache.SetCacheability(HttpCacheability.NoCache);

                    using (StringWriter sw2 = new StringWriter())
                    {
                        HtmlTextWriter hw2 = new HtmlTextWriter(sw2);
                        lbl.RenderControl(hw2);
                        StringReader sr2 = new StringReader(sw2.ToString());
                        Document pdfDoc2 = new Document(PageSize.A4, 40f, 10f, 5f, 5f);
                        HTMLWorker htmlparser2 = new HTMLWorker(pdfDoc2);
                        PdfWriter.GetInstance(pdfDoc2, Response.OutputStream);
                        pdfDoc2.Open();
                        htmlparser2.Parse(sr2);
                        pdfDoc2.Close();
                        Response.Write(pdfDoc2);
                        Response.End();
                    }

                }
            }
        }
        catch (Exception ex)
        {
            GV.DataSource = dtt;
            GV.DataBind();
            btn_checklist_Value_Update.Visible = false;
        }
    }


