                                tempPage.Add("<tr><td colspan='9'>Rs. " + String.Format("{0:0.00}", tot_AssValue) + "</td><tdSAR@123>" + String.Format("{0:0.00}", tot_ItemValue) + "</td></tr>");
                                tempPage.Add("<tr><td colspan='10'>-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------</td></tr>");
