    public string Return_ExRate_Value(string currency, string ExRate)
    {
        try
        {
            if (ExRate == "")
            {
                ExRate = "0.00";
            }
            else if (currency == "INR")
            {
                ExRate = "1";
            }
            else if (currency == "JPY" || currency == "KRW")
            {
                ExRate = Convert.ToString(Convert.ToDouble(ExRate) / 100);
            }
        }
        catch (Exception ex)
        {
            er.makeLog(ex.Message);
            
        }

        return ExRate;
    }

