                            double Final_Anti_Dump = TOTAL_ANTIDUMP_AMT - Anti_Dump_Cal2;

                            TOTAL_ANTI_AMT_LICNESE = Convert.ToString(Math.Round(Final_Anti_Dump, 2).ToString("F"));
