                                TOTAL_ANTI_AMT_LICNESE = "0.00";

                            MERIT_TOTAL_ANTI_AMT = TOTAL_ANTI_AMT_LICNESE;

                        }
                    }
                    else
                    {
                        ADD_MAX_DIFF = Convert.ToDouble(MAX_DIFF);
                        /* hide on 05-11-2024 - Sugg.by Bala sir
                        TOTAL_ANTIDUMP_AMT = (ADD_MAX_DIFF * ASSESABLE_VALUE) / 100;
