                    }
                }
                else
                {
                    //BASIC_DUTY = ASSESABLE_VALUE * Convert.ToDouble(PRODUCT_BCD_RATE) / 100;
                    double bcd_rate = ASSESABLE_VALUE * Convert.ToDouble(PRODUCT_BCD_RATE) / 100;

