                    {
                        double bcd_Amt = c_ITEM_QTY * Convert.ToDouble(CTH_SPL_AMT);
                        double cth_Amt = Convert.ToDouble(CTH_QTY1) * Convert.ToDouble(CTH_SPL_AMT);

                        if (bcd_rate >= bcd_Amt)
                        {
                            if (cth_Amt >= bcd_rate)
