            {
                if (HEALTH_CESS_CTH_CODE != "")
                {
                    Healthcess_RateVal = Math.Round(Convert.ToDouble(ASSESABLE_VALUE * Convert.ToDouble(HEALTH_CESS_RATE) / 100), 2);
