            //if (RSP_APPLICABLE == "Y")RSP condition

            //cvd_Customs_Edu_Cess = CVD * Convert.ToDouble(CETH_CVD_EDU_CESS_RATE) / 100;
            //cvd_Customs_Higher_Edu_Cess = CVD * Convert.ToDouble(CETH_CVD_SEC_EDU_CESS_RATE) / 100;

