            //TOTAL_DEBIT_DUTY = Convert.ToString(Math.Round(Convert.ToDouble(BASIC_DUTY + CVD + Customs_Edu_Cess + Customs_Higher_Edu_Cess + AddL_DUTY + NCD), 1).ToString("0.00"));
