            //26-03-2021
            //TOTAL_DEBIT_DUTY = Convert.ToString(Convert.ToDouble(BASIC_DUTY + CVD + cvd_Customs_Edu_Cess + cvd_Customs_Higher_Edu_Cess + Customs_Social_welfare + AddL_DUTY + NCD + Healthcess_RateVal).ToString("0.00"));
            TOTAL_DEBIT_DUTY = Convert.ToString(Convert.ToDouble(BASIC_DUTY + CVD + cvd_Customs_Edu_Cess + cvd_Customs_Higher_Edu_Cess + Customs_Social_welfare + AddL_DUTY + NCD + Healthcess_RateVal + AIDC_Amt).ToString("0.00"));


