                          INDIVITUAL_INSURANCE_AMOUNT = (INDIVITUAL_INVOICE_VALUE + INDIVITUAL_MISC_AMOUNT + INDIVITUAL_SVB_AMOUNT) * Convert.ToDouble(MIS_INSURANCE_RATE) / 100;
