                        double AA = INDIVITUAL_FREIGHT_AMOUNT + (INDIVITUAL_FREIGHT_AMOUNT * 0.01);
                        INDIVITUAL_SVB_AMOUNT = (INDIVITUAL_ASSESSABLE_AMOUNT - AA) *  Convert.ToDouble(SVB_ASSESABLE_RATE) / 100;
