                                            xmlContent.AppendLine("<ReleaseAdvDate>" + (string.IsNullOrEmpty(ds_SW_Lc_Dut.Tables[1].Rows[rsp]["REGISTRATION_DATE"].ToString()) ? " " : ds_SW_Lc_Dut.Tables[1].Rows[rsp]["REGISTRATION_DATE"].ToString()) + "</ReleaseAdvDate>");
                                            xmlContent.AppendLine("<RegisteredPort>" + (string.IsNullOrEmpty(ds_SW_Lc_Dut.Tables[1].Rows[rsp]["PORT_OF_LICENSE"].ToString()) ? " " : ds_SW_Lc_Dut.Tables[1].Rows[rsp]["PORT_OF_LICENSE"].ToString()) + "</RegisteredPort>");
                                            xmlContent.AppendLine("</LicenceDtl>");

                                        }
                                        xmlContent.AppendLine("</ITCLicenceDtls>");

