                                        xmlContent.AppendLine("<LicenceDtl>");
                                        xmlContent.AppendLine("<LicNo>" + " " + "</LicNo>");
                                        xmlContent.AppendLine("<LicDate>" + " " + "</LicDate>");
                                        xmlContent.AppendLine("<DebitValue>" + " " + "</DebitValue>");
                                        xmlContent.AppendLine("<Quantity>" + " " + "</Quantity>");
                                        xmlContent.AppendLine("<DocumentNo>" + " " + "</DocumentNo>");
