                                            xmlContent.AppendLine("<Insurance>" + (string.IsNullOrEmpty(ds_SW_Lc_Dut.Tables[2].Rows[0]["INDIVITUAL_INSURANCE_AMOUNT"].ToString()) ? " " : ds_SW_Lc_Dut.Tables[2].Rows[0]["INDIVITUAL_INSURANCE_AMOUNT"].ToString()) + "</Insurance>");
                                            xmlContent.AppendLine("<Commission>" + " " + "</Commission>");
                                            xmlContent.AppendLine("<Miscellaneous>" + (string.IsNullOrEmpty(ds_SW_Lc_Dut.Tables[2].Rows[0]["INDIVITUAL_MISC_AMOUNT"].ToString()) ? " " : ds_SW_Lc_Dut.Tables[2].Rows[0]["INDIVITUAL_MISC_AMOUNT"].ToString()) + "</Miscellaneous>");
                                            xmlContent.AppendLine("<CIFValue>" + (string.IsNullOrEmpty(ds_SW_Lc_Dut.Tables[2].Rows[0]["CIF_VALUE"].ToString()) ? " " : ds_SW_Lc_Dut.Tables[2].Rows[0]["CIF_VALUE"].ToString()) + "</CIFValue>");
                                            xmlContent.AppendLine("<AssessableValue>" + (string.IsNullOrEmpty(ds_SW_Lc_Dut.Tables[2].Rows[0]["ASSESSABLE_VALUE"].ToString()) ? " " : ds_SW_Lc_Dut.Tables[2].Rows[0]["ASSESSABLE_VALUE"].ToString()) + "</AssessableValue>");
                                            xmlContent.AppendLine("<TotalBasicDutyAmt>" + (string.IsNullOrEmpty(ds_SW_Lc_Dut.Tables[2].Rows[0]["BASIC_VALUE"].ToString()) ? " " : ds_SW_Lc_Dut.Tables[2].Rows[0]["BASIC_VALUE"].ToString()) + "</TotalBasicDutyAmt>");
                                            xmlContent.AppendLine("<TotalCVDAmt>" + (string.IsNullOrEmpty(ds_SW_Lc_Dut.Tables[2].Rows[0]["CVD_VALUE"].ToString()) ? " " : ds_SW_Lc_Dut.Tables[2].Rows[0]["CVD_VALUE"].ToString()) + "</TotalCVDAmt>");
                                            xmlContent.AppendLine("<TotalDutyAmt>" + (string.IsNullOrEmpty(ds_SW_Lc_Dut.Tables[2].Rows[0]["DUTY_VALUE"].ToString()) ? " " : ds_SW_Lc_Dut.Tables[2].Rows[0]["DUTY_VALUE"].ToString()) + "</TotalDutyAmt>");

